const claim = $input.first()?.json ?? {};
if (claim.claimed !== true) {
  return [];
}
return [{ json: $('Webhook Trigger').first().json }];

// 2. Code: Validate Customer Request — validate customer ID and requester context
const item = $input.first().json;
const payload = item.body || item;

const customerId = payload.customerId || null;
const workflowRunId = payload.workflowRunId || null;
const triggeredByUserId = payload.triggeredByUserId || null;

if (!customerId) {
  throw new Error('Validation Error: Missing customerId in Customer 360 request');
}

return [{
  json: {
    customerId,
    workflowRunId,
    triggeredByUserId,
    requestedAt: payload.timestamp || new Date().toISOString(),
    rawRequest: payload
  }
}];

// 9. Code: Merge Customer Timeline — normalize and combine source records with source provenance
const customerId = $('Code: Validate Customer Request').first().json.customerId;
const workflowRunId = $('Code: Validate Customer Request').first().json.workflowRunId;

const profileRes = $('HTTP Request: CRM Profile').first()?.json || {};
const interactionsRes = $('HTTP Request: Get Interactions').first()?.json;
const intelligenceRes = $('HTTP Request: Get Lead Intelligence History').first()?.json || {};
const followUpsRes = $('HTTP Request: Get Follow-up History').first()?.json || {};
const segmentsRes = $('HTTP Request: Get Segment Memberships').first()?.json;
const feedbackRes = $('HTTP Request: Get Issue/Feedback History').first()?.json;

const isError = (res) => {
  if (!res) return false;
  if (res.error) return true;
  if (typeof res.statusCode === 'number' && res.statusCode >= 400) return true;
  if (typeof res.status === 'number' && res.status >= 400) return true;
  return false;
};

// CRM Profile
const profileError = isError(profileRes);
if (profileError || !profileRes?.id) {
  throw new Error('Customer 360 Aborted: CRM customer profile could not be loaded');
}
const customer = profileRes;
const convertedLeads = Array.isArray(profileRes.convertedLeads) ? profileRes.convertedLeads : [];

// Interactions
const interactionsError = isError(interactionsRes);
const interactions = (!interactionsError && Array.isArray(interactionsRes)) ? interactionsRes : [];

// Intelligence
const intelligenceError = isError(intelligenceRes);
const qualifications = (!intelligenceError && Array.isArray(intelligenceRes.qualifications)) ? intelligenceRes.qualifications : [];
const enrichments = (!intelligenceError && Array.isArray(intelligenceRes.enrichments)) ? intelligenceRes.enrichments : [];
const scores = (!intelligenceError && Array.isArray(intelligenceRes.scores)) ? intelligenceRes.scores : [];

// Follow-ups
const followUpsError = isError(followUpsRes);
const enrollments = (!followUpsError && Array.isArray(followUpsRes.enrollments)) ? followUpsRes.enrollments : [];
const executions = (!followUpsError && Array.isArray(followUpsRes.executions)) ? followUpsRes.executions : [];

// Segments
const segmentsError = isError(segmentsRes);
const segments = (!segmentsError && Array.isArray(segmentsRes)) ? segmentsRes : [];

// Feedback
const feedbackError = isError(feedbackRes);
const feedbackList = (!feedbackError && Array.isArray(feedbackRes)) ? feedbackRes : (!feedbackError && Array.isArray(feedbackRes?.data) ? feedbackRes.data : []);

// Compute data-dependent sourceCoverage (preserving source-fetch failures as UNAVAILABLE instead of EMPTY)
const sourceCoverage = {
  crmProfile: profileError ? 'UNAVAILABLE' : (customer.id ? 'AVAILABLE' : 'EMPTY'),
  interactions: interactionsError ? 'UNAVAILABLE' : (interactions.length > 0 ? 'AVAILABLE' : 'EMPTY'),
  leadIntelligence: intelligenceError ? 'UNAVAILABLE' : ((qualifications.length > 0 || enrichments.length > 0 || scores.length > 0) ? 'AVAILABLE' : 'EMPTY'),
  followUps: followUpsError ? 'UNAVAILABLE' : ((enrollments.length > 0 || executions.length > 0) ? 'AVAILABLE' : 'EMPTY'),
  segments: segmentsError ? 'UNAVAILABLE' : (segments.length > 0 ? 'AVAILABLE' : 'EMPTY'),
  customerIssues: 'NOT_CONNECTED',
  customerFeedback: feedbackError ? 'UNAVAILABLE' : (feedbackList.length > 0 ? 'AVAILABLE' : 'EMPTY')
};

const prompt = `
You are an enterprise CRM Customer 360 Intelligence Agent.
Synthesize a comprehensive 360 executive profile for this B2B customer based on all verified CRM touchpoints.

=== CUSTOMER PROFILE ===
- Account Name: ${customer.name || 'N/A'}
- Company: ${customer.companyName || 'N/A'}
- Domain/Website: ${customer.companyWebsite || 'N/A'}
- Industry: ${customer.industry || 'General Business'}
- Company Size: ${customer.companySize || 'Unknown'} employees
- Current Status: ${customer.status || 'ACTIVE'}
- Contact Email: ${customer.email || 'N/A'}
- Segment Memberships: ${segments.map(s => s.segmentName || s.segmentId).join(', ') || 'Standard Account'}

=== INTERACTION TIMELINE & SIGNALS ===
- Converted Leads Count: ${convertedLeads.length}
- Recorded Touchpoints: ${sourceCoverage.interactions === 'UNAVAILABLE' ? 'Service unavailable during scan' : interactions.length + ' recorded'}
- Recent Interactions:
${interactions.slice(0, 5).map(i => `  • [${i.occurredAt || 'Recent'}] ${i.type}: ${i.subject || i.content || 'Discussion'}`).join('\n') || (sourceCoverage.interactions === 'UNAVAILABLE' ? '  • Interaction service unavailable.' : '  • No direct calls/emails recorded.')}

=== HISTORICAL INTELLIGENCE & FOLLOW-UP ===
- Lead Qualification: ${qualifications[0]?.status || (sourceCoverage.leadIntelligence === 'UNAVAILABLE' ? 'Service unavailable' : 'N/A')} (Confidence: ${qualifications[0]?.confidence || 'N/A'})
- Lead Score: ${scores[0]?.label || 'WARM'} (${scores[0]?.score || 'N/A'}/100)
- Follow-up Cadence: ${enrollments.length} campaigns active/completed

=== DATA SOURCE COVERAGE ===
- CRM Profile: ${sourceCoverage.crmProfile}
- Interactions: ${sourceCoverage.interactions}
- Intelligence: ${sourceCoverage.leadIntelligence}
- Follow-ups: ${sourceCoverage.followUps}
- Segments: ${sourceCoverage.segments}
- Issues & Support Tickets: ${sourceCoverage.customerIssues} (External helpdesk not connected)
- Customer Feedback: ${sourceCoverage.customerFeedback}

Respond ONLY with valid JSON conforming to this exact schema:
{
  "summary": "Concise 2-3 sentence executive synthesis summarizing customer maturity and relationship health.",
  "keyStrengths": ["Strength 1", "Strength 2"],
  "potentialRisks": ["Risk or churn signal 1", "Risk 2"],
  "growthOpportunities": ["Expansion or upsell opportunity 1", "Opportunity 2"],
  "recommendedNextAction": "High-impact tactical next action for the Account Executive or CSM."
}
`;

return [{
  json: {
    customerId,
    workflowRunId,
    customer,
    convertedLeads,
    interactions,
    intelligence: { qualifications, enrichments, scores },
    followUps: { enrollments, executions },
    segments,
    sourceCoverage,
    prompt
  }
}];

// 11. Code: Validate Customer 360 Output — require structured fields and report actual AI outcome
const response = $input.first().json;
const prep = $('Code: Merge Customer Timeline').first().json;

const customerId = prep.customerId;
const workflowRunId = prep.workflowRunId;
const sourceCoverage = prep.sourceCoverage;

let geminiOutput = null;
try {
  const rawText = response.candidates?.[0]?.content?.parts?.[0]?.text;
  if (rawText) {
    geminiOutput = JSON.parse(rawText);
  }
} catch (e) {
  geminiOutput = null;
}

if (geminiOutput && geminiOutput.summary) {
  return [{
    json: {
      customerId,
      workflowRunId,
      status: 'SUCCESS',
      summary: geminiOutput.summary,
      keyStrengths: Array.isArray(geminiOutput.keyStrengths) ? geminiOutput.keyStrengths : [],
      potentialRisks: Array.isArray(geminiOutput.potentialRisks) ? geminiOutput.potentialRisks : [],
      growthOpportunities: Array.isArray(geminiOutput.growthOpportunities) ? geminiOutput.growthOpportunities : [],
      recommendedNextAction: geminiOutput.recommendedNextAction || 'Schedule regular executive review.',
      sourceCoverage,
      rawAIOutput: geminiOutput,
      evaluatedAt: new Date().toISOString()
    }
  }];
} else {
  // Accurately report failure when Gemini call fails or returns non-JSON, do not fabricate fake AI outputs
  return [{
    json: {
      customerId,
      workflowRunId,
      status: 'FAILED',
      errorMessage: 'Gemini AI Customer 360 synthesis failed or returned invalid response format.',
      summary: null,
      keyStrengths: [],
      potentialRisks: [],
      growthOpportunities: [],
      recommendedNextAction: null,
      sourceCoverage,
      rawAIOutput: response,
      evaluatedAt: new Date().toISOString()
    }
  }];
}
